mapper.select:
SELECT
FROM venue v LEFT JOIN ( SELECT venue_id, COUNT(*) AS session_count FROM performance_session GROUP BY venue_id ) s_stat ON s_stat.venue_id = v.venue_id
ORDER BY v.city_name ASC, v.venue_id ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM venue
WHERE city_name = #{cityName}
  AND venue_name = #{venueName}
  AND address = #{address}

  AND venue_id <> #{excludeVenueId}
